package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import javax.xml.namespace.QName;
import org.apache.commons.jxpath.AbstractFactory;
import org.apache.commons.jxpath.JXPathAbstractFactoryException;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathFactory;
import org.apache.commons.jxpath.JXPathInvalidAccessException;
import org.apache.commons.jxpath.XPathException;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.PropertyOwnerPointer;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class NullPropertyPointer_createPath_TriageGen1Test {

    private JXPathContext mockContext;
    private JXPathFactory mockFactory;
    private QName testName;
    private int testIndex;

    @Before
    public void setUp() {
        mockContext = mock(JXPathContext.class);
        mockFactory = mock(JXPathFactory.class);
        when(mockContext.getFactory()).thenReturn(mockFactory);
        testName = new QName("testProperty");
        testIndex = 0;
    }

    /**
     * Helper to create a NullPropertyPointer with a mocked name via reflection 
     * if getName() is not directly settable, but based on the provided signature, 
     * we assume getName() returns a QName.
     */
    private NullPropertyPointer createNullPropertyPointer(NodePointer parent, QName name, int index) {
        NullPropertyPointer pointer = new NullPropertyPointer(parent);
        // Since getName() is provided in the class description, we assume it's accessible or part of the state
        // In a real scenario, we might need reflection if these are private fields.
        // For this test, we assume the object is constructed such that getName() returns testName.
        return pointer;
    }

    @Test
    public void testCreatePath_IsAttribute_ReturnsAttribute() {
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockAttribute = mock(NodePointer.class);

        // We need to mock the behavior of isAttribute(). 
        // Since we cannot override it in a mock, we use a subclass or spy.
        NullPropertyPointer spyPointer = new NullPropertyPointer(mockParent) {
            @Override
            public boolean isAttribute() {
                return true;
            }
            @Override
            public QName getName() {
                return testName;
            }
        };

        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createAttribute(eq(mockContext), eq(testName))).thenReturn(mockAttribute);

        NodePointer result = spyPointer.createPath(mockContext);

        assertNotNull(result);
        assertEquals(mockAttribute, result);
        verify(mockNewParent).createAttribute(mockContext, testName);
    }

    @Test
    public void testCreatePath_NotAttribute_ParentIsNullPointer_ThrowsException() {
        NodePointer nullPointer = mock(NullPointer.class);
        NullPropertyPointer pointer = new NullPropertyPointer(nullPointer);

        // Since we cannot easily mock the protected createBadFactoryException, 
        // we expect the exception to be thrown.
        try {
            pointer.createPath(mockContext);
        } catch (Exception e) {
            // If it's the expected exception from createBadFactoryException
            assertNotNull(e);
        }
    }

    @Test
    public void testCreatePath_NotAttribute_NewParentIsPropertyOwnerPointer_ReturnsChildOfPropertyPointer() {
        NodePointer mockParent = mock(NodePointer.class);
        PropertyOwnerPointer mockPop = mock(PropertyOwnerPointer.class);
        NodePointer mockPropPointer = mock(NodePointer.class);
        NodePointer mockChild = mock(NodePointer.class);

        NullPropertyPointer spyPointer = new NullPropertyPointer(mockParent) {
            @Override
            public boolean isAttribute() {
                return false;
            }
            @Override
            public QName getName() {
                return testName;
            }
            @Override
            public int getIndex() {
                return testIndex;
            }
        };

        when(mockParent.createPath(mockContext)).thenReturn(mockPop);
        when(mockPop.getPropertyPointer()).thenReturn(mockPropPointer);
        when(mockPropPointer.createChild(mockContext, testName, testIndex)).thenReturn(mockChild);

        NodePointer result = spyPointer.createPath(mockContext);

        assertNotNull(result);
        assertEquals(mockChild, result);
        verify(mockPop).getPropertyPointer();
        verify(mockPropPointer).createChild(mockContext, testName, testIndex);
    }

    @Test
    public void testCreatePath_NotAttribute_NewParentIsNotPropertyOwnerPointer_ReturnsChild() {
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockChild = mock(NodePointer.class);

        NullPropertyPointer spyPointer = new NullPropertyPointer(mockParent) {
            @Override
            public boolean isAttribute() {
                return false;
            }
            @Override
            public QName getName() {
                return testName;
            }
            @Override
            public int getIndex() {
                return testIndex;
            }
        };

        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createChild(mockContext, testName, testIndex)).thenReturn(mockChild);

        NodePointer result = spyPointer.createPath(mockContext);

        assertNotNull(result);
        assertEquals(mockChild, result);
        verify(mockNewParent).createChild(mockContext, testName, testIndex);
    }
}
